    "«Клятва боли»: начиная с 4-й карты за ход немедленно наносит 3 урона (сначала по броне) и получает +1 к ярости. Накладывает Тлен и Слабость.": "«Клятва болю»: починаючи з 4-ї карти за хід негайно завдає 3 шкоди (спочатку по броні) та отримує +1 до люті. Накладає Тління та Слабкість.",
