    "Начинает бой с Костяным лучником. Призывает скелетов (до 3 врагов) и усиливает всех живых союзников (+6 брони и +2 к урону).": "Починає бій із Кістяним лучником. Прикликанняає скелетів (до 3 ворогів) і посилює всіх живих союзників (+6 броні та +2 до шкоди).",
