    "Вампиризм: кровожадные удары исцеляют Палача на долю урона, прошедшего по вашему HP (броня и слуги блокируют отхил). При HP ниже 50% впадает в Кровавое неистовство (+2 ярости).": "Вампіризм: кровожерні удари зцілюють Ката на частку шкоди, що пройшла по вашому HP (броня та слуги блокують зцілення). За HP нижче 50% впадає у Криваву лють (+2 люті).",
