    "Ослабляет вас, заражает Тленом и забивает колоду временными проклятиями. Волна мора наносит +2 урона за каждое проклятие в вашей колоде (макс. +8).": "Ослаблює вас, заражає Тлінням і забиває колоду тимчасовими прокляттями. Хвиля мору завдає +2 шкоди за кожне прокляття у вашій колоді (макс. +8).",
