    "Занимает место в руке. Если останется в руке в конце хода — накладывает на вас 1 Тлен. Разыграйте (1 энергии), чтобы изгнать до конца боя.": "Займає місце в руці. Якщо залишиться в руці наприкінці ходу — накладає на вас 1 Тління. Розіграйте (1 енергії), щоб вигнати до кінця бою.",

