    "Вампиризм · Неистовство": "Вампіризм · Шаленство",
    "Кровожадные удары исцеляют Палача на процент урона, прошедшего по вашему HP. Броня и слуги блокируют отхил. При HP ниже 50% получает +2 Ярости.": "Кровожерні удари зцілюють Ката на відсоток шкоди, що пройшла по вашому HP. Броня та слуги блокують лікування. За HP нижче 50% отримує +2 Люті.",
    "Владычица мора": "Володарка мору",
    "Забивает колоду проклятиями. Волна мора наносит +2 урона за каждую карту проклятия в вашей колоде (макс. +8).": "Забиває колоду прокляттями. Хвиля мору завдає +2 шкоди за кожну карту прокляття у вашій колоді (макс. +8).",
    "Враг оглушён и пропустит свой ход, не совершая никаких действий.": "Ворог оглушений і пропустить свій хід, не виконуючи жодних дій.",
    "Карта должна иметь уникальный id": "Карта повинна мати унікальний id",
