    "Проклятия в сброс": "Прокляття у скидання",

    // --- Shadow Reaper Events & Outcomes ---
    "Пакт Тени и Плоти (-4 HP)": "Пакт Тіні й Плоті (-4 HP)",
    "Пакт Тени и Плоти": "Пакт Тіні й Плоті",
    "Отдать 4 HP за постоянный бонус: +1 к урону всех атак и +2 брони в начале каждого боя.": "Віддати 4 HP за постійний бонус: +1 до шкоди всіх атак і +2 броні на початку кожного бою.",
    "Кровь капает на рунный камень. Клинок и Тень отзываются тёмным резонансом.": "Кров крапає на рунний камінь. Клинок і Тінь озиваються темним резонансом.",
    "Награда: +1 к урону всех атак и +2 брони в начале каждого боя.": "Нагорода: +1 до шкоди всіх атак і +2 броні на початку кожного бою.",
    "Постоянно: +1 урон атак, +2 брони в начале боя": "Постійно: +1 шкода атак, +2 броні на початку бою",
    "— Наконец-то! Хоть кто-то из молодых решил послушать настоящего мастера. Садись, сейчас расскажу пару трюков из старых походов.": "— Нарешті! Хоч хтось із молодих вирішив послухати справжнього майстра. Сідай, зараз розкажу кілька хитрощів зі старих походів.",
    "Попросить снаряжение для следующего боя.": "Попросити спорядження для наступного бою.",
    "«Старые доспехи ещё послужат…»": "«Старі обладунки ще послужать…»",
    "Старик усмехается и кивает на сундук у стены.": "Старий усміхається і киває на скриню біля стіни.",
    "— Раз ты действуешь в одиночку, мёртвые помощники тебе ни к чему. Забирай теневой наруч и склянку эссенции — пригодятся.": "— Раз ти дієш поодинці, мертві помічники тобі ні до чого. Забирай тіньовий наруч і склянку есенції — стануть у пригоді.",
    "Получаешь постоянное для забега усиление: все твои атаки получают +1 к урону.": "Отримуєш постійне для походу посилення: усі твої атаки отримують +1 до шкоди.",
    "Ты поднимаешь сломанную корону и возлагаешь её на голову. Тень древнего полководца впитывается в твои клинки.": "Ти піднімаєш зламану корону й покладаєш її на голову. Тінь давнього полководця вбирається у твої клинки.",
    "Теперь каждый твой удар разит глубже.": "Тепер кожен твій удар разить глибше.",
    "Награда: все ваши атаки получают +1 к урону до конца забега.": "Нагорода: усі ваші атаки отримують +1 до шкоди до кінця походу.",
    "«Щит и эхо клинков…»": "«Щит і відлуння клинків…»",
    "Ты забираешь зачарованные наручи авангарда и кристалл застывшей маны. Сила древнего строя укроет тебя в следующей схватке.": "Ти забираєш зачаровані наручі авангарду та кристал застиглої мани. Сила давнього строю вкриє тебе в наступній сутичці.",
    "Получить +16 брони и +1 ману в начале следующего боя.": "Отримати +16 броні та +1 ману на початку наступного бою.",
    "Награда: +16 брони и +1 маны в начале следующего боя.": "Нагорода: +16 броні та +1 мани на початку наступного бою.",
    "На следующий бой: +16 брони, +1 маны": "На наступний бій: +16 броні, +1 мани",
    "Потерять 5 HP, получить 1 случайную редкую карту Тени или Жатвы.": "Втратити 5 HP, отримати 1 випадкову рідкісну карту Тіні або Жнив.",
    "«Наконец-то покой…»": "«Нарешті спокій…»",
    "Ты разрываешь цепи, сковывающие душу. На мгновение алтарь озаряется ярким светом, а призрак впервые за сотни лет улыбается.": "Ти розриваєш ланцюги, що сковують душу. На мить вівтар осявається яскравим світлом, а привид уперше за сотні років усміхається.",
    "— Спасибо… Я почти забыл, каково это — быть свободным.": "— Дякую… Я майже забув, як це — бути вільним.",
    "Душа постепенно растворяется в воздухе, оставляя после себя рунический отпечаток. Ты чувствуешь, как силы покидают твоё тело, но вместе с ними получаешь новые знания.": "Душа поступово розчиняється в повітрі, залишаючи по собі рунічний відбиток. Ти відчуваєш, як сили покидають твоє тіло, але разом із ними здобуваєш нові знання.",
    "Цена: 5 HP.": "Ціна: 5 HP.",
    "Награда: случайная редкая карта жнеца.": "Нагорода: випадкова рідкісна карта женця.",
    "«Будущее уже написано…»": "«Майбутнє вже написано…»",
    "В конце страницы проступает последняя фраза:": "Наприкінці сторінки проступає остання фраза:",
    "— Теперь ты знаешь, что тебя ждёт. Посмотрим, сможешь ли ты это изменить.": "— Тепер ти знаєш, що на тебе чекає. Побачимо, чи зможеш ти це змінити.",
    "Награда: узнаёшь состав следующего противника и его намерения.": "Нагорода: дізнаєшся склад наступного противника та його наміри.",

