    "Извлечение искры": "Вилучення іскри",
    "5 урона · +1 Осколок · убийство: +1 карта": "5 шкоди · +1 Уламок · убивство: +1 карта",
    "Наносите 5 урона и получаете +1 Осколок души. Если цель погибает — добор 1 карты.": "Завдаєте 5 шкоди й отримуєте +1 Уламок душі. Якщо ціль гине — добір 1 карти.",
    "8 урона · +1 Осколок · убийство: +1 карта": "8 шкоди · +1 Уламок · убивство: +1 карта",
    "Наносите 8 урона и получаете +1 Осколок души. Если цель погибает — добор 1 карты.": "Завдаєте 8 шкоди й отримуєте +1 Уламок душі. Якщо ціль гине — добір 1 карти.",

