    "9 ур. · Форма Тени · +1 карта": "9 шк. · Форма Тіні · +1 карта",
    "Наносите 9 урона. Переход в Форму Тени и добор 1 карты.": "Завдаєте 9 шкоди. Перехід у Форму Тіні та добір 1 карти.",

