    "+7 брони · сброс 1 → +1 Осколок": "+7 броні · скидання 1 → +1 Уламок",
    "Получаете 7 брони. Сбросьте 1 карту из руки, чтобы получить +1 Осколок души.": "Отримуєте 7 броні. Скиньте 1 карту з руки, щоб отримати +1 Уламок душі.",
    "+10 брони · сброс 1 → +1 Осколок": "+10 броні · скидання 1 → +1 Уламок",
    "Получаете 10 брони. Сбросьте 1 карту из руки, чтобы получить +1 Осколок души.": "Отримуєте 10 броні. Скиньте 1 карту з руки, щоб отримати +1 Уламок душі.",

