    "Добор 2 карт, затем сбросьте 1 карту. В Форме Тени: +1 Осколок души.": "Добір 2 карт, потім скиньте 1 карту. У Формі Тіні: +1 Уламок душі.",
    "+3 карты · сброс 1 · Тень: +1 Осколок": "+3 карти · скидання 1 · Тінь: +1 Уламок",
    "Добор 3 карт, затем сбросьте 1 карту. В Форме Тени: +1 Осколок души.": "Добір 3 карт, потім скиньте 1 карту. У Формі Тіні: +1 Уламок душі.",

