    "7 ур. · в Тени без штрафа и игнор брони": "7 шк. · у Тіні без штрафу й ігнор броні",
    "Наносите 7 урона. В Форме Тени не получает штраф -25% и игнорирует Броню цели.": "Завдаєте 7 шкоди. У Формі Тіні не отримує штраф -25% та ігнорує Броню цілі.",
    "10 ур. · в Тени без штрафа и игнор брони": "10 шк. · у Тіні без штрафу й ігнор броні",
    "Наносите 10 урона. В Форме Тени не получает штраф -25% и игнорирует Броню цели.": "Завдаєте 10 шкоди. У Формі Тіні не отримує штраф -25% та ігнорує Броню цілі.",

