    "Снять Бесплотность или 4 Ярости · +7 брони": "Зняти Безтілесність або 4 Люті · +7 броні",
    "Снимает с выбранного врага Бесплотность или 4 ед. Ярости. Получаете +7 брони.": "Знімає з обраного ворога Безтілесність або 4 од. Люті. Отримуєте +7 броні.",

