    "10 ур. · срыв баффа/призыва · -50% атаки врага": "10 шк. · зрив бафу/прикликання · -50% атаки ворога",
    "Наносите 10 урона. Отменяет усиленную атаку и призыв врага в этом ходу (враг наносит 50% урона).": "Завдаєте 10 шкоди. Скасовує посилену атаку та прикликання ворога в цьому ході (ворог завдає 50% шкоди).",
    "14 ур. · срыв баффа/призыва · -50% атаки врага": "14 шк. · зрив бафу/прикликання · -50% атаки ворога",
    "Наносите 14 урона. Отменяет усиленную атаку и призыв врага в этом ходу (враг наносит 50% урона).": "Завдаєте 14 шкоди. Скасовує посилену атаку та прикликання ворога в цьому ході (ворог завдає 50% шкоди).",

    "Сеть кандалов": "Сітка кайданів",
    "+4 Оков всем врагам · Тень: +6 брони": "+4 Оков усім ворогам · Тінь: +6 броні",
    "Накладывает +4 Оков ВСЕМ врагам. В Форме Тени получаете +6 брони.": "Накладає +4 Оков УСІМ ворогам. У Формі Тіні отримуєте +6 броні.",
