    "50% входящего урона отражается во врага с Оковами": "50% вхідної шкоди відбивається у ворога з Оковами",
    "До конца хода 50% получаемого вами урона отражается во врага с Оковами.": "До кінця ходу 50% отримуваної вами шкоди відбивається у ворога з Оковами.",

    "Кража брони": "Викрадення броні",
    "Забрать до 10 Брони у врага себе": "Забрати до 10 Броні у ворога собі",
    "Забирает до 10 Брони у выбранного врага и передаёт её вам.": "Забирає до 10 Броні в обраного ворога та передає її вам.",
    "Забрать до 14 Брони у врага себе": "Забрати до 14 Броні у ворога собі",
