    "Владычица мора": "Володарка мору",
    "Кровожадные удары исцеляют Палача на процент урона, прошедшего по вашему HP. Броня и слуги блокируют отхил. При HP ниже 50% получает +2 Ярости.": "Кровожерливі удари зцілюють Ката на відсоток шкоди, що пройшла по вашому HP. Броня та слуги блокують зцілення. При HP нижче 50% отримує +2 Люті.",
    "Забивает колоду проклятиями. Волна мора наносит +2 урона за каждую карту проклятия в вашей колоде (макс. +8).": "Засмічує колоду прокляттями. Хвиля мору завдає +2 шкоди за кожну карту прокляття у вашій колоді (макс. +8).",
