  function ukPlural(n, one, few, many) {
    const abs = Math.abs(Number(n)) || 0;
    const mod100 = abs % 100;
    const mod10 = abs % 10;
    if (mod10 === 1 && mod100 !== 11) return one;
    if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return few;
    return many;
  }

  // Helper to translate quoted names inside «...» for a given language
  function translateQuotedFor(name, lang) {
    if (!name) return name;
    const pack = getPack(lang);
    if (!pack) return name;
    const plus = name.endsWith("+");
    const base = plus ? name.slice(0, -1).trim() : name.trim();
    const tr = (Object.prototype.hasOwnProperty.call(pack.exact, base) ? pack.exact[base] : null) || translateSingleLineFor(base, lang);
    return plus ? tr + "+" : tr;
  }

  function translateQuoted(name) {
    return translateQuotedFor(name, "uk");
  }

  function translateDotTail(rest) {
    if (!rest) return rest;
    if (rest.indexOf(" · ") !== -1) {
      return rest.split(" · ").map(function (part) {
        return part ? translateSingleLine(part) : part;
      }).join(" · ");
    }
    return translateInlineFragments(rest);
  }

  // Ordered dynamic template patterns for interpolated runtime strings
